const body = $input.first().json.body || $input.first().json;

const deliveryId = body.deliveryId || body.id;
const awb = body.awb || 'UNKNOWN_AWB';
const courier = body.courier || 'Courier Partner';
const ndrReason = body.ndrReason || 'Customer unavailable during delivery attempt';
const orderNumber = body.orderNumber || 'ORD-UNKNOWN';
const customerEmail = body.customerEmail || 'customer@example.com';
const customerName = body.customerName || 'Valued Customer';

// Determine resolution strategy based on carrier exception reason
let recoveryStrategy = 'RESCHEDULE_DELIVERY_SLOT';
let suggestedSlots = ['Tomorrow 10 AM - 2 PM', 'Tomorrow 2 PM - 6 PM', 'Day After Tomorrow Any Time'];

const lowerReason = ndrReason.toLowerCase();
if (lowerReason.includes('address') || lowerReason.includes('pincode') || lowerReason.includes('landmark')) {
  recoveryStrategy = 'COLLECT_LANDMARK_AND_ADDRESS';
} else if (lowerReason.includes('refuse') || lowerReason.includes('reject') || lowerReason.includes('cod amount')) {
  recoveryStrategy = 'CONFIRM_INTENT_OR_CANCEL';
}

return {
  json: {
    deliveryId,
    awb,
    courier,
    ndrReason,
    customerEmail,
    customerName,
    orderNumber,
    recoveryStrategy,
    suggestedSlots,
    emailSubject: `Important: Re-schedule your delivery for Order #${orderNumber} (${courier})`,
    emailMessage: `Hi ${customerName}, your delivery partner (${courier}) attempted delivery for Order #${orderNumber} but could not complete it: "${ndrReason}". Please select a convenient time slot and nearest landmark using the secure link.`,
    status: 'NDR_INTERVENTION_INITIATED',
    timestamp: new Date().toISOString()
  }
};
